def _nanmedian(a):
    a = np.asarray(a, dtype=float)
    a = a[np.isfinite(a)]
    return float(np.nanmedian(a)) if a.size else np.nan

def _nanmean(a):
    a = np.asarray(a, dtype=float)
    a = a[np.isfinite(a)]
    return float(np.nanmean(a)) if a.size else np.nan
drr_hyp = x_drr[(hyp == 1) & np.isfinite(x_drr)]
drr_no = x_drr[(hyp == 0) & np.isfinite(x_drr)]
dhr_hyp = x_dhr[(hyp == 1) & np.isfinite(x_dhr)]
dhr_no = x_dhr[(hyp == 0) & np.isfinite(x_dhr)]
result['delta_rr_median_by_hypotension'] = {'sbp_lt90_within_pm2min': _nanmedian(drr_hyp), 'no_sbp_lt90_within_pm2min': _nanmedian(drr_no), 'n_hyp': int(drr_hyp.size), 'n_no': int(drr_no.size)}
result['delta_hr_median_by_hypotension'] = {'sbp_lt90_within_pm2min': _nanmedian(dhr_hyp), 'no_sbp_lt90_within_pm2min': _nanmedian(dhr_no), 'n_hyp': int(dhr_hyp.size), 'n_no': int(dhr_no.size)}

def _spearman(x, y):
    m = np.isfinite(x) & np.isfinite(y)
    if np.sum(m) < 3:
        return {'rho': np.nan, 'p': np.nan, 'n': int(np.sum(m))}
    rho, p = stats.spearmanr(x[m], y[m])
    return {'rho': float(rho), 'p': float(p), 'n': int(np.sum(m))}
result['spearman_nadir_spo2_vs_delta_rr'] = _spearman(y_nadir, x_drr)
result['spearman_nadir_spo2_vs_delta_hr'] = _spearman(y_nadir, x_dhr)
interpretation['spo2_desaturation_coupling_summary'] = f'Across {n} SpO₂<90 runs, nadir SpO₂ showed Spearman ρ={result['spearman_nadir_spo2_vs_delta_rr']['rho']:.3f} (p={result['spearman_nadir_spo2_vs_delta_rr']['p']:.3g}, n={result['spearman_nadir_spo2_vs_delta_rr']['n']}) with ΔRR and ρ={result['spearman_nadir_spo2_vs_delta_hr']['rho']:.3f} (p={result['spearman_nadir_spo2_vs_delta_hr']['p']:.3g}, n={result['spearman_nadir_spo2_vs_delta_hr']['n']}) with ΔHR, with points labeled by whether SBP<90 occurred within ±2 min of nadir to contextualize compensatory responses vs hemodynamic instability.'

